import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CQxpk36T.js";const u=JSON.parse('{"title":"Film et captures","description":"","frontmatter":{},"headers":[],"relativePath":"developpement/medias.md","filePath":"developpement/medias.md","lastUpdated":1793563901000}'),n={name:"developpement/medias.md"};function l(r,e,o,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="film-et-captures" tabindex="-1">Film et captures <a class="header-anchor" href="#film-et-captures" aria-label="Permalink to &quot;Film et captures&quot;">​</a></h1><p>Le film et les captures de ce site et du README sont générés depuis la maison d&#39;exemple en mode démo : rien de personnel n&#39;y apparaît, et on les refait en une commande après un changement visible.</p><h2 id="les-captures" tabindex="-1">Les captures <a class="header-anchor" href="#les-captures" aria-label="Permalink to &quot;Les captures&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> screens</span></span></code></pre></div><p>Écrit <code>docs/public/screens/*.jpg</code> : sept captures de bureau (1920 × 1080) et trois de téléphone (975 × 2110). Chaque capture met la démo dans un état précis : heure, météo, onglet, bâtiment sélectionné, étage en coupe, lampes allumées. Moins d&#39;une minute.</p><h2 id="le-film" tabindex="-1">Le film <a class="header-anchor" href="#le-film" aria-label="Permalink to &quot;Le film&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> video</span></span></code></pre></div><p>Écrit <code>docs/public/demo.mp4</code> (1080p, H.264) et son affiche <code>docs/public/demo-poster.jpg</code>. Environ trois minutes de capture et quinze secondes d&#39;encodage.</p><p>Le scénario, les titres et les transitions sont dans <code>scripts/media/film.js</code>, injecté dans la page :</p><ul><li>une <strong>horloge virtuelle</strong> remplace <code>performance.now</code>, <code>Date</code>, <code>requestAnimationFrame</code>, les minuteries et les animations CSS : chaque image avance d&#39;exactement 1/30 s, quelle que soit la vitesse de la machine ;</li><li>les titres, bandeaux, volets et touchers simulés sont des calques CSS animés ;</li><li>chaque image est capturée par le protocole de Chrome, puis passée à ffmpeg (<a href="https://github.com/eugeneware/ffmpeg-static" target="_blank" rel="noreferrer">ffmpeg-static</a>, installé avec le projet).</li></ul><table tabindex="0"><thead><tr><th>Variable</th><th></th></tr></thead><tbody><tr><td><code>VIDEO_GPU=0</code></td><td>Rendu logiciel (machine sans carte graphique)</td></tr><tr><td><code>VIDEO_KEEP=1</code></td><td>Garde les images capturées</td></tr><tr><td><code>VIDEO_ENCODE_ONLY=1</code></td><td>Réencode les images gardées sans refaire la capture</td></tr></tbody></table><p>Sans ffmpeg avec H.264, le film sort en WebM (VP9).</p><h2 id="la-base-commune" tabindex="-1">La base commune <a class="header-anchor" href="#la-base-commune" aria-label="Permalink to &quot;La base commune&quot;">​</a></h2><p><code>scripts/media/app.mjs</code> démarre le serveur de développement (maison d&#39;exemple), lance Chromium avec la carte graphique et une densité de pixels forcée, fixe le hasard (mêmes animaux, mêmes nuages à chaque fois) et attend que la scène et les polices soient prêtes.</p>',14)])])}const h=a(n,[["render",l]]);export{u as __pageData,h as default};
